-- Reset y carga limpia de los 63 proveedores auditados (2026-11-13)
-- Ejecutar en el SQL Editor de Supabase

BEGIN;

-- 1. Asegurar columnas nuevas en public.suppliers
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS phone_fixed text;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS phone_mobile text;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS website text;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS hours text;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS branches jsonb;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS frequency integer DEFAULT 1;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS updated_at text;

-- 2. Vaciar registros anteriores (84 mezclados/obsoletos) y reiniciar secuencia
TRUNCATE TABLE public.suppliers RESTART IDENTITY;

-- 3. Insertar los 63 proveedores unificados y verificados

SELECT setval(pg_get_serial_sequence('public.suppliers', 'id'), (SELECT COALESCE(MAX(id), 1) FROM public.suppliers));

COMMIT;
